import{_ as e,o as t,c as i,a5 as n}from"./chunks/framework.B-qY3dMa.js";const k=JSON.parse('{"title":"Dify 接入指南","description":"","frontmatter":{"title":"Dify 接入指南","date":"2026-05-18T00:00:00.000Z","category":"拓展","tags":["Dify","Agent","工作流","接入教程"]},"headers":[],"relativePath":"connect/dify.md","filePath":"connect/dify.md","lastUpdated":1779073000000}'),s={name:"connect/dify.md"};function r(o,a,d,p,l,h){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="dify-接入指南" tabindex="-1">Dify 接入指南 <a class="header-anchor" href="#dify-接入指南" aria-label="Permalink to &quot;Dify 接入指南&quot;">​</a></h1><p>零代码构建 AI 工作流和 Agent，接入熊猫Token解锁全部模型。</p><p><strong>预计用时：10 分钟 · 适用场景：Agent / 工作流开发 · 部署方式：云端 / 本地</strong></p><hr><h2 id="什么是-dify" tabindex="-1">什么是 Dify？ <a class="header-anchor" href="#什么是-dify" aria-label="Permalink to &quot;什么是 Dify？&quot;">​</a></h2><p>Dify 是一个开源的 LLM 应用开发平台，提供可视化工作流编排、RAG（检索增强生成）、Agent 构建等功能。接入熊猫Token平台后，可以在 Dify 中使用所有主流大模型，无需单独申请各厂商 API Key。</p><hr><h2 id="step-01-获取-dify" tabindex="-1">Step 01：获取 Dify <a class="header-anchor" href="#step-01-获取-dify" aria-label="Permalink to &quot;Step 01：获取 Dify&quot;">​</a></h2><h3 id="方式一-使用-dify-云端版-推荐" tabindex="-1">方式一：使用 Dify 云端版（推荐） <a class="header-anchor" href="#方式一-使用-dify-云端版-推荐" aria-label="Permalink to &quot;方式一：使用 Dify 云端版（推荐）&quot;">​</a></h3><p>直接访问 <a href="https://cloud.dify.ai" target="_blank" rel="noreferrer">cloud.dify.ai</a>，注册账号即可免费使用，无需安装。</p><h3 id="方式二-docker-本地部署" tabindex="-1">方式二：Docker 本地部署 <a class="header-anchor" href="#方式二-docker-本地部署" aria-label="Permalink to &quot;方式二：Docker 本地部署&quot;">​</a></h3><p>如果需要本地部署，确保已安装 Docker，然后执行：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 克隆仓库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/langgenius/dify.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dify/docker</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启动服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>启动后访问 <code>http://localhost/install</code> 完成初始化。</p><hr><h2 id="step-02-获取熊猫token-api-key" tabindex="-1">Step 02：获取熊猫Token API Key <a class="header-anchor" href="#step-02-获取熊猫token-api-key" aria-label="Permalink to &quot;Step 02：获取熊猫Token API Key&quot;">​</a></h2><h3 id="_1-登录并创建令牌" tabindex="-1">1. 登录并创建令牌 <a class="header-anchor" href="#_1-登录并创建令牌" aria-label="Permalink to &quot;1. 登录并创建令牌&quot;">​</a></h3><p>访问 <a href="https://www.pandatoken.net" target="_blank" rel="noreferrer">www.pandatoken.net</a>，进入「控制台」→「令牌」，新建令牌并复制。</p><hr><h2 id="step-03-在-dify-中添加模型供应商" tabindex="-1">Step 03：在 Dify 中添加模型供应商 <a class="header-anchor" href="#step-03-在-dify-中添加模型供应商" aria-label="Permalink to &quot;Step 03：在 Dify 中添加模型供应商&quot;">​</a></h2><h3 id="_1-进入模型供应商设置" tabindex="-1">1. 进入模型供应商设置 <a class="header-anchor" href="#_1-进入模型供应商设置" aria-label="Permalink to &quot;1. 进入模型供应商设置&quot;">​</a></h3><p>登录 Dify 后，点击右上角头像 → 「设置」→「模型供应商」。</p><h3 id="_2-选择-openai-兼容" tabindex="-1">2. 选择 OpenAI 兼容 <a class="header-anchor" href="#_2-选择-openai-兼容" aria-label="Permalink to &quot;2. 选择 OpenAI 兼容&quot;">​</a></h3><p>在模型供应商列表中，找到「OpenAI-API-compatible」（OpenAI 兼容），点击「添加模型」。</p><h3 id="_3-填写配置信息" tabindex="-1">3. 填写配置信息 <a class="header-anchor" href="#_3-填写配置信息" aria-label="Permalink to &quot;3. 填写配置信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>配置项</th><th>填写内容</th></tr></thead><tbody><tr><td>模型名称</td><td>例如 <code>deepseek-v3</code>（与平台模型 ID 保持一致）</td></tr><tr><td>API Key</td><td>你从熊猫Token平台复制的令牌</td></tr><tr><td>API Endpoint URL</td><td><code>https://www.pandatoken.net/v1</code></td></tr><tr><td>模型类型</td><td>LLM</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">添加多个模型</p><p>每个模型需要单独添加一条配置，可重复此步骤添加多个模型（如 deepseek-r1、gpt-4o 等）。</p></div><h3 id="_4-保存并验证" tabindex="-1">4. 保存并验证 <a class="header-anchor" href="#_4-保存并验证" aria-label="Permalink to &quot;4. 保存并验证&quot;">​</a></h3><p>点击「保存」，Dify 会自动验证连接。出现绿色勾表示配置成功。</p><p>配置成功后，在创建应用时即可从模型列表中选择熊猫Token平台的模型。</p><h3 id="_5-开始构建应用" tabindex="-1">5. 开始构建应用 <a class="header-anchor" href="#_5-开始构建应用" aria-label="Permalink to &quot;5. 开始构建应用&quot;">​</a></h3><p>回到首页，点击「创建应用」，选择聊天助手、工作流或 Agent，在模型设置中选择你刚添加的模型，即可开始构建。</p><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>验证失败，提示 connection error</strong></p><p>请确认 API Endpoint URL 填写为 <code>https://www.pandatoken.net/v1</code>，末尾带 <code>/v1</code>。</p><p><strong>本地 Docker 部署的 Dify 如何连接外网 API？</strong></p><p>默认 Docker 部署已能访问外网，直接按上述步骤填写即可。如果网络受限，请检查 Docker 的网络配置。</p><hr><p>配置完成！Dify 已成功接入熊猫Token平台，零代码构建你的专属 AI Agent。</p>`,40)])])}const f=e(s,[["render",r]]);export{k as __pageData,f as default};
